const std = @import("std");
const math = std.math;

pub const Error = error{
    InvalidDimension,
    DivisionByZero,
};

pub fn rmsnormForward(
    output: []f32,
    input: []const f32,
    weight: []const f32,
    eps: f32,
) Error!void {
    const normalized_shape = input.len;
    if (normalized_shape == 0) {
        return;
    }
    if (output.len != normalized_shape or weight.len != normalized_shape) {
        return Error.InvalidDimension;
    }

    var sum_sq: f64 = 0.0;
    for (input) |x| {
        sum_sq += @as(f64, x) * @as(f64, x);
    }

    const mean_sq: f64 = sum_sq / @as(f64, normalized_shape);
    if (mean_sq + @as(f64, eps) < 0) {
        // Avoid sqrt of negative number if eps is negative
        return Error.InvalidDimension;
    }
    const rsqrt_val: f32 = @floatCast(1.0 / math.sqrt(mean_sq + @as(f64, eps)));

    for (input, weight, 0..) |x, w, i| {
        output[i] = x * rsqrt_val * w;
    }
}

pub fn rmsnormBackward(
    grad_input: []f32,
    grad_weight_contrib: []f32,
    grad_output: []const f32,
    input: []const f32,
    weight: []const f32,
    eps: f32,
) Error!void {
    const normalized_shape = input.len;
    if (normalized_shape == 0) {
        return;
    }
    if (grad_input.len != normalized_shape or
        grad_weight_contrib.len != normalized_shape or
        grad_output.len != normalized_shape or
        weight.len != normalized_shape)
    {
        return Error.InvalidDimension;
    }

    var sum_sq: f64 = 0.0;
    for (input) |x| {
        sum_sq += @as(f64, x) * @as(f64, x);
    }

    const mean_sq: f64 = sum_sq / @as(f64, normalized_shape);
    if (mean_sq + @as(f64, eps) < 0) {
        return Error.InvalidDimension;
    }
    const rsqrt_val: f32 = @floatCast(1.0 / math.sqrt(mean_sq + @as(f64, eps)));
    const rsqrt_pow3_val = rsqrt_val * rsqrt_val * rsqrt_val;

    var sum_gwx: f64 = 0.0;
    for (grad_output, weight, input) |g, w, x| {
        sum_gwx += @as(f64, g) * @as(f64, w) * @as(f64, x);
    }

    const common_term = @as(f32, sum_gwx) * rsqrt_pow3_val / @as(f32, normalized_shape);

    for (grad_output, weight, input, 0..) |g, w, x, i| {
        grad_input[i] = w * rsqrt_val * g - x * common_term;
        grad_weight_contrib[i] = g * x * rsqrt_val;
    }
}

pub fn layernormForward(
    output: []f32,
    input: []const f32,
    weight: []const f32,
    bias: ?[]const f32,
    eps: f32,
) Error!void {
    const normalized_shape = input.len;
    if (normalized_shape == 0) {
        return;
    }
    if (output.len != normalized_shape or weight.len != normalized_shape) {
        return Error.InvalidDimension;
    }
    if (bias) |b| {
        if (b.len != normalized_shape) return Error.InvalidDimension;
    }

    var sum: f64 = 0.0;
    var sum_sq: f64 = 0.0;
    for (input) |x| {
        const val: f64 = x;
        sum += val;
        sum_sq += val * val;
    }

    const shape_f64 = @as(f64, normalized_shape);
    const mean: f64 = sum / shape_f64;
    const mean_sq: f64 = sum_sq / shape_f64;
    const variance: f64 = mean_sq - mean * mean;

    if (variance + @as(f64, eps) < 0) {
        return Error.InvalidDimension;
    }
    const inv_std: f32 = @floatCast(1.0 / math.sqrt(variance + @as(f64, eps)));

    for (input, weight, 0..) |x, w, i| {
        const b_val = if (bias) bias.?[i] else 0.0;
        const normalized = (x - @as(f32, mean)) * inv_std;
        output[i] = normalized * w + b_val;
    }
}

pub fn geluForward(output: []f32, input: []const f32) Error!void {
    if (output.len != input.len) return Error.InvalidDimension;
    const sqrt2_inv: f32 = 0.7071067811865475;
    for (input, 0..) |x, i| {
        const cdf = 0.5 * (1.0 + math.erf(x * sqrt2_inv));
        output[i] = x * cdf;
    }
}

pub fn geluBackward(
    grad_input: []f32,
    grad_output: []const f32,
    input: []const f32,
) Error!void {
    if (grad_input.len != input.len or grad_output.len != input.len) {
        return Error.InvalidDimension;
    }
    const sqrt2_inv: f32 = 0.7071067811865475;
    const pi_inv_sqrt2: f32 = 0.3989422804014327;
    for (input, grad_output, 0..) |x, g, i| {
        const cdf = 0.5 * (1.0 + math.erf(x * sqrt2_inv));
        const pdf = math.exp(-0.5 * x * x) * pi_inv_sqrt2;
        const grad = cdf + x * pdf;
        grad_input[i] = g * grad;
    }
}

pub fn softmaxForward(output: []f32, input: []const f32) Error!void {
    const dim_size = input.len;
    if (dim_size == 0) {
        return;
    }
    if (output.len != dim_size) {
        return Error.InvalidDimension;
    }

    var max_val: f32 = -math.floatMax(f32);
    for (input) |x| {
        max_val = @max(max_val, x);
    }

    var sum_exp: f64 = 0.0;
    var temp_output = std.ArrayList(f32).init(std.heap.page_allocator);
    defer temp_output.deinit();
    try temp_output.resize(dim_size);

    for (input, 0..) |x, i| {
        const exp_val = math.exp(x - max_val);
        temp_output.items[i] = @floatCast(exp_val);
        sum_exp += exp_val;
    }

    if (sum_exp == 0.0) {
        for (output, 0..) |_, i| {
            output[i] = 0.0;
        }
        return;
    }

    const inv_sum_exp: f32 = @floatCast(1.0 / sum_exp);
    for (temp_output.items, 0..) |y, i| {
        output[i] = y * inv_sum_exp;
    }
}
import Mathlib.Data.Real.Basic
import Mathlib.Data.Vector.Basic
import Mathlib.Analysis.SpecialFunctions.Exp
import Mathlib.Analysis.SpecialFunctions.Sqrt
import Mathlib.Analysis.SpecialFunctions.Erf
import Mathlib.Data.Real.Pi.Basic

noncomputable section

open Real
open Vector

def sum {n : Nat} (v : Vector ℝ n) : ℝ :=
  List.sum v.toList

def sumSq {n : Nat} (v : Vector ℝ n) : ℝ :=
  List.sum (v.toList.map (fun x => x ^ 2))

def mean {n : Nat} (v : Vector ℝ n) : ℝ :=
  if h : n = 0 then 0 else sum v / n

def variance {n : Nat} (v : Vector ℝ n) : ℝ :=
  if h : n = 0 then 0 else (sumSq v / n) - (mean v) ^ 2

def maxVal {n : Nat} (v : Vector ℝ n) : ℝ :=
  if h : n = 0 then 0 else v.toList.maximum.getD 0

def spec_rmsnorm {n : Nat} (input weight : Vector ℝ n) (eps : ℝ) : Vector ℝ n :=
  if h : n = 0 then Vector.nil
  else
    let mean_sq := sumSq input / n
    let rsqrt_val := rsqrt (mean_sq + eps)
    (input.map (fun x => x * rsqrt_val)) *ᵥ weight

def spec_rmsnorm_backward {n : Nat} (g_out input weight : Vector ℝ n) (eps : ℝ)
  : Vector ℝ n × Vector ℝ n :=
  if h : n = 0 then (Vector.nil, Vector.nil)
  else
    let mean_sq := sumSq input / n
    let rsqrt_val := rsqrt (mean_sq + eps)
    let rsqrt_pow3_val := rsqrt_val ^ 3
    let sum_gwx := sum (g_out *ᵥ weight *ᵥ input)
    let common_term := sum_gwx * rsqrt_pow3_val / n
    let grad_input := (weight.map (fun w => w * rsqrt_val) *ᵥ g_out) -ᵥ (input.map (fun x => x * common_term))
    let grad_weight_contrib := g_out *ᵥ input *ᵥ (Vector.replicate n rsqrt_val)
    (grad_input, grad_weight_contrib)

def spec_layernorm {n : Nat} (input weight : Vector ℝ n) (bias : Option (Vector ℝ n)) (eps : ℝ) : Vector ℝ n :=
  if h : n = 0 then Vector.nil
  else
    let m := mean input
    let v := variance input
    let inv_std := rsqrt (v + eps)
    let normalized := (input.map (fun x => x - m)).map (fun x => x * inv_std)
    let scaled := normalized *ᵥ weight
    match bias with
    | some b => scaled +ᵥ b
    | none => scaled

def spec_gelu (x : ℝ) : ℝ :=
  x * (1 / 2 * (1 + erf (x / sqrt 2)))

def spec_gelu_backward (g_out x : ℝ) : ℝ :=
  let cdf := 1 / 2 * (1 + erf (x / sqrt 2))
  let pdf := exp (-1 / 2 * x ^ 2) / sqrt (2 * π)
  g_out * (cdf + x * pdf)

def spec_softmax {n : Nat} (input : Vector ℝ n) : Vector ℝ n :=
  if h : n = 0 then Vector.nil
  else
    let exps := input.map exp
    let sum_exps := sum exps
    if sum_exps = 0 then Vector.replicate n 0
    else exps.map (fun x => x / sum_exps)

def impl_rmsnorm {n : Nat} (input weight : Vector ℝ n) (eps : ℝ) : Vector ℝ n :=
  if h : n = 0 then Vector.nil
  else
    let sum_sq_val := sumSq input
    let mean_sq := sum_sq_val / n
    let rsqrt_val := rsqrt (mean_sq + eps)
    (input.map (fun x => x * rsqrt_val)) *ᵥ weight

def impl_layernorm {n : Nat} (input weight : Vector ℝ n) (bias : Option (Vector ℝ n)) (eps : ℝ) : Vector ℝ n :=
  if h : n = 0 then Vector.nil
  else
    let sum_val := sum input
    let sum_sq_val := sumSq input
    let mean_val := sum_val / n
    let mean_sq_val := sum_sq_val / n
    let variance_val := mean_sq_val - mean_val ^ 2
    let inv_std := rsqrt (variance_val + eps)
    let normalized := (input.map (fun x => x - mean_val)).map (fun x => x * inv_std)
    let scaled := normalized *ᵥ weight
    match bias with
    | some b => scaled +ᵥ b
    | none => scaled

def impl_softmax {n : Nat} (input : Vector ℝ n) : Vector ℝ n :=
  if h : n = 0 then Vector.nil
  else
    let max_v := maxVal input
    let shifted := input.map (fun x => x - max_v)
    let exps := shifted.map exp
    let sum_exps := sum exps
    if sum_exps = 0 then Vector.replicate n 0
    else exps.map (fun x => x / sum_exps)

theorem rmsnorm_correct {n : Nat} (input weight : Vector ℝ n) (eps : ℝ) :
  impl_rmsnorm input weight eps = spec_rmsnorm input weight eps := by
  unfold impl_rmsnorm spec_rmsnorm; split_ifs <;> rfl

theorem layernorm_correct {n : Nat} (input weight : Vector ℝ n) (bias : Option (Vector ℝ n)) (eps : ℝ) :
  impl_layernorm input weight bias eps = spec_layernorm input weight bias eps := by
  unfold impl_layernorm spec_layernorm mean variance; split_ifs <;> rfl

theorem softmax_correct {n : Nat} (input : Vector ℝ n) :
  impl_softmax input = spec_softmax input := by
  unfold impl_softmax spec_softmax
  by_cases h_n_zero : n = 0
  . rw [dif_pos h_n_zero, dif_pos h_n_zero]
  . rw [dif_neg h_n_zero, dif_neg h_n_zero]
    let max_v := maxVal input
    let exps_spec := input.map exp
    let sum_exps_spec := sum exps_spec
    let shifted := input.map (fun x => x - max_v)
    let exps_impl := shifted.map exp
    let sum_exps_impl := sum exps_impl
    have h_sum_impl_spec : sum_exps_impl = sum_exps_spec / exp max_v := by
      unfold sum at *; unfold exps_impl; unfold exps_spec
      rw [map_map, map_map]
      have h_comp : (fun x => exp (x - max_v)) = (fun y => y / exp max_v) ∘ exp := by
        funext z; simp; rw [sub_eq_add_neg, exp_add, mul_div_right_comm]
      rw [h_comp, map_map, List.sum_map_div]
    by_cases h_sum_spec_zero : sum_exps_spec = 0
    . rw [dif_pos h_sum_spec_zero]
      have h_sum_impl_zero : sum_exps_impl = 0 := by
        rw [h_sum_impl_spec, h_sum_spec_zero, zero_div]
      rw [dif_pos h_sum_impl_zero]
    . rw [dif_neg h_sum_spec_zero]
      have h_sum_impl_ne_zero : sum_exps_impl ≠ 0 := by
        rw [h_sum_impl_spec]; simp [h_sum_spec_zero, exp_ne_zero]
      rw [dif_neg h_sum_impl_ne_zero]
      congr
      ext i
      simp
      rw [sub_eq_add_neg, exp_add]
      rw [h_sum_impl_spec]
      field_simp [exp_ne_zero max_v]
      ring

end

const std = @import("std");
const math = std.math;

pub const BFloat16 = packed struct {
    bits: u16,

    pub fn fromFloat(f: f32) BFloat16 {
        const bits: u32 = @bitCast(f);
        const truncated: u16 = @intCast((bits + 0x8000) >> 16);
        return BFloat16{ .bits = truncated };
    }

    pub fn toFloat(self: BFloat16) f32 {
        const bits: u32 = @as(u32, self.bits) << 16;
        return @bitCast(bits);
    }

    pub fn fromBits(bits: u16) BFloat16 {
        return BFloat16{ .bits = bits };
    }
};

pub const NormError = error{
    InvalidNormalizedShape,
    InvalidInputSize,
    NullPointer,
    NumericalInstability,
};

pub const SoftmaxError = error{
    ZeroDimension,
    InvalidDimensions,
    NullPointer,
    NumericalInstability,
};

pub fn validateNormParams(numel: usize, normalized_shape: usize) NormError!usize {
    if (normalized_shape == 0) return NormError.InvalidNormalizedShape;
    if (numel == 0) return NormError.InvalidInputSize;
    if (numel % normalized_shape != 0) return NormError.InvalidInputSize;
    return numel / normalized_shape;
}

pub fn rmsNormForward(
    input: []const BFloat16,
    weight: []const BFloat16,
    output: []BFloat16,
    normalized_shape: usize,
    eps: f32,
) NormError!void {
    if (input.len == 0) return NormError.InvalidInputSize;
    if (normalized_shape == 0) return NormError.InvalidNormalizedShape;
    if (input.len % normalized_shape != 0) return NormError.InvalidInputSize;

    const n_rows = input.len / normalized_shape;
    if (output.len < input.len) return NormError.InvalidInputSize;
    if (weight.len < normalized_shape) return NormError.InvalidInputSize;

    var row: usize = 0;
    while (row < n_rows) : (row += 1) {
        const row_start = row * normalized_shape;
        const row_end = row_start + normalized_shape;

        var sum_sq: f64 = 0.0;
        var i: usize = row_start;
        while (i < row_end) : (i += 1) {
            const val: f64 = @floatCast(input[i].toFloat());
            sum_sq += val * val;
        }

        const mean_sq: f64 = sum_sq / @as(f64, @floatFromInt(normalized_shape));
        const eps_f64: f64 = @floatCast(eps);
        const denom: f64 = math.sqrt(mean_sq + eps_f64);

        if (denom == 0.0 or !math.isFinite(denom)) return NormError.NumericalInstability;

        const rsqrt: f64 = 1.0 / denom;

        i = row_start;
        while (i < row_end) : (i += 1) {
            const val: f64 = @floatCast(input[i].toFloat());
            const w: f64 = @floatCast(weight[i - row_start].toFloat());
            const result: f32 = @floatCast(val * rsqrt * w);
            output[i] = BFloat16.fromFloat(result);
        }
    }
}

pub fn rmsNormBackward(
    grad_output: []const BFloat16,
    input: []const BFloat16,
    weight: []const BFloat16,
    grad_input: []BFloat16,
    grad_weight: ?[]BFloat16,
    normalized_shape: usize,
    eps: f32,
) NormError!void {
    if (grad_output.len == 0) return NormError.InvalidInputSize;
    if (normalized_shape == 0) return NormError.InvalidNormalizedShape;
    if (grad_output.len % normalized_shape != 0) return NormError.InvalidInputSize;

    const n_rows = grad_output.len / normalized_shape;
    if (input.len < grad_output.len) return NormError.InvalidInputSize;
    if (weight.len < normalized_shape) return NormError.InvalidInputSize;
    if (grad_input.len < grad_output.len) return NormError.InvalidInputSize;
    if (grad_weight) |gw| {
        if (gw.len < normalized_shape) return NormError.InvalidInputSize;
    }

    if (grad_weight) |gw| {
        @memset(@as([]u8, @as([*]u8, @ptrCast(gw.ptr))[0..gw.len * @sizeOf(BFloat16)]), 0);
    }

    var row: usize = 0;
    while (row < n_rows) : (row += 1) {
        const row_start = row * normalized_shape;
        const row_end = row_start + normalized_shape;

        var sum_sq: f64 = 0.0;
        var i: usize = row_start;
        while (i < row_end) : (i += 1) {
            const val: f64 = @floatCast(input[i].toFloat());
            sum_sq += val * val;
        }

        const mean_sq: f64 = sum_sq / @as(f64, @floatFromInt(normalized_shape));
        const eps_f64: f64 = @floatCast(eps);
        const denom: f64 = math.sqrt(mean_sq + eps_f64);

        if (denom == 0.0 or !math.isFinite(denom)) return NormError.NumericalInstability;

        const rsqrt: f64 = 1.0 / denom;
        const rsqrt_cubed: f64 = rsqrt * rsqrt * rsqrt;
        const n_f64: f64 = @floatFromInt(normalized_shape);

        var sum_gwx: f64 = 0.0;
        i = row_start;
        while (i < row_end) : (i += 1) {
            const g: f64 = @floatCast(grad_output[i].toFloat());
            const w: f64 = @floatCast(weight[i - row_start].toFloat());
            const x: f64 = @floatCast(input[i].toFloat());
            sum_gwx += g * w * x;
        }

        i = row_start;
        while (i < row_end) : (i += 1) {
            const g: f64 = @floatCast(grad_output[i].toFloat());
            const w: f64 = @floatCast(weight[i - row_start].toFloat());
            const x: f64 = @floatCast(input[i].toFloat());

            const term1: f64 = w * rsqrt * g;
            const term2: f64 = x * sum_gwx * rsqrt_cubed / n_f64;
            const grad: f64 = term1 - term2;

            const grad_in: f32 = @floatCast(grad);
            grad_input[i] = BFloat16.fromFloat(grad_in);

            if (grad_weight) |gw| {
                const idx = i - row_start;
                const existing: f64 = @floatCast(gw[idx].toFloat());
                const new_val: f64 = existing + g * x * rsqrt;
                gw[idx] = BFloat16.fromFloat(@floatCast(new_val));
            }
        }
    }
}

pub fn layerNormForward(
    input: []const BFloat16,
    weight: []const BFloat16,
    bias: ?[]const BFloat16,
    output: []BFloat16,
    normalized_shape: usize,
    eps: f32,
) NormError!void {
    if (input.len == 0) return NormError.InvalidInputSize;
    if (normalized_shape == 0) return NormError.InvalidNormalizedShape;
    if (input.len % normalized_shape != 0) return NormError.InvalidInputSize;

    const n_rows = input.len / normalized_shape;
    if (output.len < input.len) return NormError.InvalidInputSize;
    if (weight.len < normalized_shape) return NormError.InvalidInputSize;
    if (bias) |b| {
        if (b.len < normalized_shape) return NormError.InvalidInputSize;
    }

    var row: usize = 0;
    while (row < n_rows) : (row += 1) {
        const row_start = row * normalized_shape;
        const row_end = row_start + normalized_shape;

        var sum: f64 = 0.0;
        var sum_sq: f64 = 0.0;
        var i: usize = row_start;
        while (i < row_end) : (i += 1) {
            const val: f64 = @floatCast(input[i].toFloat());
            sum += val;
            sum_sq += val * val;
        }

        const n_f64: f64 = @floatFromInt(normalized_shape);
        const mean: f64 = sum / n_f64;
        const mean_sq: f64 = sum_sq / n_f64;
        const variance_biased: f64 = mean_sq - mean * mean;
        const variance: f64 = @max(0.0, variance_biased);
        const eps_f64: f64 = @floatCast(eps);
        const var_plus_eps: f64 = variance + eps_f64;
        const inv_std: f64 = 1.0 / math.sqrt(var_plus_eps);

        if (!math.isFinite(inv_std)) return NormError.NumericalInstability;

        i = row_start;
        while (i < row_end) : (i += 1) {
            const val: f64 = @floatCast(input[i].toFloat());
            const w: f64 = @floatCast(weight[i - row_start].toFloat());
            const b: f64 = if (bias) |bs| @floatCast(bs[i - row_start].toFloat()) else 0.0;
            const normalized: f64 = (val - mean) * inv_std;
            const result: f32 = @floatCast(normalized * w + b);
            output[i] = BFloat16.fromFloat(result);
        }
    }
}

pub fn geluApproximate(x: f32) f32 {
    const sqrt_2_over_pi: f32 = 0.7978845608028654;
    const x3 = x * x * x;
    const inner = sqrt_2_over_pi * (x + 0.044715 * x3);
    const tanh_val = math.tanh(inner);
    return 0.5 * x * (1.0 + tanh_val);
}

pub fn geluExact(x: f32) f32 {
    const sqrt2: f32 = 1.4142135623730951;
    const arg = x / sqrt2;
    const erf_val = math.erf(arg);
    return 0.5 * x * (1.0 + erf_val);
}

pub fn geluForward(
    input: []const BFloat16,
    output: []BFloat16,
    approximate: bool,
) NormError!void {
    if (input.len == 0) return;
    if (output.len < input.len) return NormError.InvalidInputSize;

    var i: usize = 0;
    while (i < input.len) : (i += 1) {
        const x = input[i].toFloat();
        const y = if (approximate) geluApproximate(x) else geluExact(x);
        output[i] = BFloat16.fromFloat(y);
    }
}

pub fn geluBackward(
    grad_output: []const BFloat16,
    input: []const BFloat16,
    grad_input: []BFloat16,
    approximate: bool,
) NormError!void {
    if (grad_output.len == 0) return;
    if (input.len < grad_output.len) return NormError.InvalidInputSize;
    if (grad_input.len < grad_output.len) return NormError.InvalidInputSize;

    var i: usize = 0;
    while (i < grad_output.len) : (i += 1) {
        const x = input[i].toFloat();
        const g = grad_output[i].toFloat();

        const grad: f32 = if (approximate) geluApproximateDerivative(x) else geluExactDerivative(x);
        grad_input[i] = BFloat16.fromFloat(g * grad);
    }
}

fn geluApproximateDerivative(x: f32) f32 {
    const sqrt_2_over_pi: f32 = 0.7978845608028654;
    const coeff_3_044715: f32 = 0.134145;
    const x2 = x * x;
    const x3 = x2 * x;
    const tanh_arg = sqrt_2_over_pi * (x + 0.044715 * x3);
    const tanh_val = math.tanh(tanh_arg);
    const sech_sq = 1.0 - tanh_val * tanh_val;
    const inner_deriv = sqrt_2_over_pi * (1.0 + coeff_3_044715 * x2);
    return 0.5 * (1.0 + tanh_val) + 0.5 * x * sech_sq * inner_deriv;
}

fn geluExactDerivative(x: f32) f32 {
    const sqrt2: f32 = 1.4142135623730951;
    const inv_sqrt_2pi: f32 = 0.3989422804014327;
    const cdf = 0.5 * (1.0 + math.erf(x / sqrt2));
    const pdf = math.exp(-0.5 * x * x) * inv_sqrt_2pi;
    return cdf + x * pdf;
}

pub fn softmaxForward(
    input: []const BFloat16,
    output: []BFloat16,
    outer_size: usize,
    dim_size: usize,
    inner_size: usize,
) SoftmaxError!void {
    if (outer_size == 0 or inner_size == 0) return;
    if (dim_size == 0) return SoftmaxError.ZeroDimension;
    const total_size = outer_size * dim_size * inner_size;
    if (input.len < total_size) return SoftmaxError.InvalidDimensions;
    if (output.len < total_size) return SoftmaxError.InvalidDimensions;

    var outer: usize = 0;
    while (outer < outer_size) : (outer += 1) {
        var inner: usize = 0;
        while (inner < inner_size) : (inner += 1) {
            const base_offset = outer * dim_size * inner_size + inner;

            var max_val: f32 = -math.inf(f32);
            var d: usize = 0;
            while (d < dim_size) : (d += 1) {
                const idx = base_offset + d * inner_size;
                const val = input[idx].toFloat();
                if (val > max_val) max_val = val;
            }

            if (!math.isFinite(max_val)) return SoftmaxError.NumericalInstability;

            var sum_exp: f64 = 0.0;
            d = 0;
            var exp_vals = std.ArrayList(f64).init(std.heap.page_allocator);
            defer exp_vals.deinit();

            while (d < dim_size) : (d += 1) {
                const idx = base_offset + d * inner_size;
                const val: f64 = @floatCast(input[idx].toFloat());
                const exp_val = math.exp(val - @as(f64, @floatCast(max_val)));
                sum_exp += exp_val;
                try exp_vals.append(exp_val);
            }

            if (sum_exp == 0.0 or !math.isFinite(sum_exp)) {
                d = 0;
                while (d < dim_size) : (d += 1) {
                    const idx = base_offset + d * inner_size;
                    output[idx] = BFloat16.fromFloat(1.0 / @as(f32, @floatFromInt(dim_size)));
                }
            } else {
                d = 0;
                while (d < dim_size) : (d += 1) {
                    const idx = base_offset + d * inner_size;
                    const normalized: f32 = @floatCast(exp_vals.items[d] / sum_exp);
                    output[idx] = BFloat16.fromFloat(normalized);
                }
            }
        }
    }
}

pub fn rmsNormForwardStrided(
    input: []const BFloat16,
    weight: []const BFloat16,
    output: []BFloat16,
    n_rows: usize,
    normalized_shape: usize,
    input_row_stride: usize,
    output_row_stride: usize,
    eps: f32,
) NormError!void {
    if (normalized_shape == 0) return NormError.InvalidNormalizedShape;
    if (n_rows == 0) return;

    var row: usize = 0;
    while (row < n_rows) : (row += 1) {
        const input_row_start = row * input_row_stride;
        const output_row_start = row * output_row_stride;

        var sum_sq: f64 = 0.0;
        var i: usize = 0;
        while (i < normalized_shape) : (i += 1) {
            const val: f64 = @floatCast(input[input_row_start + i].toFloat());
            sum_sq += val * val;
        }

        const mean_sq: f64 = sum_sq / @as(f64, @floatFromInt(normalized_shape));
        const eps_f64: f64 = @floatCast(eps);
        const denom: f64 = math.sqrt(mean_sq + eps_f64);

        if (denom == 0.0 or !math.isFinite(denom)) return NormError.NumericalInstability;

        const rsqrt: f64 = 1.0 / denom;

        i = 0;
        while (i < normalized_shape) : (i += 1) {
            const val: f64 = @floatCast(input[input_row_start + i].toFloat());
            const w: f64 = @floatCast(weight[i].toFloat());
            const result: f32 = @floatCast(val * rsqrt * w);
            output[output_row_start + i] = BFloat16.fromFloat(result);
        }
    }
}

pub fn layerNormForwardStrided(
    input: []const BFloat16,
    weight: []const BFloat16,
    bias: ?[]const BFloat16,
    output: []BFloat16,
    n_rows: usize,
    normalized_shape: usize,
    input_row_stride: usize,
    output_row_stride: usize,
    eps: f32,
) NormError!void {
    if (normalized_shape == 0) return NormError.InvalidNormalizedShape;
    if (n_rows == 0) return;

    var row: usize = 0;
    while (row < n_rows) : (row += 1) {
        const input_row_start = row * input_row_stride;
        const output_row_start = row * output_row_stride;

        var sum: f64 = 0.0;
        var sum_sq: f64 = 0.0;
        var i: usize = 0;
        while (i < normalized_shape) : (i += 1) {
            const val: f64 = @floatCast(input[input_row_start + i].toFloat());
            sum += val;
            sum_sq += val * val;
        }

        const n_f64: f64 = @floatFromInt(normalized_shape);
        const mean: f64 = sum / n_f64;
        const mean_sq: f64 = sum_sq / n_f64;
        const variance_biased: f64 = mean_sq - mean * mean;
        const variance: f64 = @max(0.0, variance_biased);
        const eps_f64: f64 = @floatCast(eps);
        const var_plus_eps: f64 = variance + eps_f64;
        const inv_std: f64 = 1.0 / math.sqrt(var_plus_eps);

        if (!math.isFinite(inv_std)) return NormError.NumericalInstability;

        i = 0;
        while (i < normalized_shape) : (i += 1) {
            const val: f64 = @floatCast(input[input_row_start + i].toFloat());
            const w: f64 = @floatCast(weight[i].toFloat());
            const b: f64 = if (bias) |bs| @floatCast(bs[i].toFloat()) else 0.0;
            const normalized: f64 = (val - mean) * inv_std;
            const result: f32 = @floatCast(normalized * w + b);
            output[output_row_start + i] = BFloat16.fromFloat(result);
        }
    }
}

pub fn geluForwardSingle(x: f32, approximate: bool) f32 {
    return if (approximate) geluApproximate(x) else geluExact(x);
}

pub fn geluBackwardSingle(x: f32, grad_output: f32, approximate: bool) f32 {
    const grad = if (approximate) geluApproximateDerivative(x) else geluExactDerivative(x);
    return grad_output * grad;
}

pub fn softmaxForward1D(input: []const BFloat16, output: []BFloat16) SoftmaxError!void {
    if (input.len == 0) return;
    if (output.len < input.len) return SoftmaxError.InvalidDimensions;

    var max_val: f32 = -math.inf(f32);
    var i: usize = 0;
    while (i < input.len) : (i += 1) {
        const val = input[i].toFloat();
        if (val > max_val) max_val = val;
    }

    if (!math.isFinite(max_val)) return SoftmaxError.NumericalInstability;

    var sum_exp: f64 = 0.0;
    i = 0;
    while (i < input.len) : (i += 1) {
        const val: f64 = @floatCast(input[i].toFloat());
        sum_exp += math.exp(val - @as(f64, @floatCast(max_val)));
    }

    if (sum_exp == 0.0 or !math.isFinite(sum_exp)) {
        const uniform: f32 = 1.0 / @as(f32, @floatFromInt(input.len));
        i = 0;
        while (i < input.len) : (i += 1) {
            output[i] = BFloat16.fromFloat(uniform);
        }
        return;
    }

    i = 0;
    while (i < input.len) : (i += 1) {
        const val: f64 = @floatCast(input[i].toFloat());
        const exp_val = math.exp(val - @as(f64, @floatCast(max_val)));
        const normalized: f32 = @floatCast(exp_val / sum_exp);
        output[i] = BFloat16.fromFloat(normalized);
    }
}

test "rms_norm_forward_basic" {
    const allocator = std.testing.allocator;
    const normalized_shape: usize = 4;
    const n_rows: usize = 2;
    const total = normalized_shape * n_rows;

    var input = try allocator.alloc(BFloat16, total);
    var weight = try allocator.alloc(BFloat16, normalized_shape);
    var output = try allocator.alloc(BFloat16, total);
    defer allocator.free(input);
    defer allocator.free(weight);
    defer allocator.free(output);

    var i: usize = 0;
    while (i < total) : (i += 1) {
        input[i] = BFloat16.fromFloat(1.0);
    }
    i = 0;
    while (i < normalized_shape) : (i += 1) {
        weight[i] = BFloat16.fromFloat(1.0);
    }

    try rmsNormForward(input, weight, output, normalized_shape, 1e-5);

    i = 0;
    while (i < total) : (i += 1) {
        const out_val = output[i].toFloat();
        try std.testing.expectApproxEqAbs(1.0, out_val, 0.01);
    }
}

test "softmax_forward_basic" {
    const allocator = std.testing.allocator;
