namespace NormalizationKernels

def BFloat16 : Type := Fin 65536

namespace BFloat16

def fromFloat (f : Float) : BFloat16 :=
  ⟨(f.toUInt32 + 32768) / 65536⟩

def toFloat (bf : BFloat16) : Float :=
  Float.ofUInt32 bf.val * 65536

def fromBits (bits : UInt16) : BFloat16 := ⟨bits.toNat % 65536⟩

end BFloat16

inductive NormError : Type
  | invalidNormalizedShape : NormError
  | invalidInputSize : NormError
  | nullPointer : NormError
  | numericalInstability : NormError
  deriving DecidableEq

inductive SoftmaxError : Type
  | zeroDimension : SoftmaxError
  | invalidDimensions : SoftmaxError
  | nullPointer : SoftmaxError
  | numericalInstability : SoftmaxError
  deriving DecidableEq

def validateNormParams (numel : Nat) (normalized_shape : Nat) : Except NormError Nat :=
  if normalized_shape = 0 then Except.error NormError.invalidNormalizedShape
  else if numel = 0 then Except.error NormError.invalidInputSize
  else if numel % normalized_shape ≠ 0 then Except.error NormError.invalidInputSize
  else Except.ok (numel / normalized_shape)

theorem validateNormParams_valid (numel normalized_shape : Nat) 
    (h1 : normalized_shape ≠ 0) 
    (h2 : numel ≠ 0) 
    (h3 : numel % normalized_shape = 0) :
    validateNormParams numel normalized_shape = Except.ok (numel / normalized_shape) := by
  native_decide

theorem validateNormParams_zero_shape (numel : Nat) :
    validateNormParams numel 0 = Except.error NormError.invalidNormalizedShape := by
  native_decide

theorem validateNormParams_zero_numel (normalized_shape : Nat) (h : normalized_shape ≠ 0) :
    validateNormParams 0 normalized_shape = Except.error NormError.invalidInputSize := by
  native_decide

theorem validateNorm_params_non_divisible (numel normalized_shape : Nat) 
    (h1 : normalized_shape ≠ 0) 
    (h2 : numel ≠ 0) 
    (h3 : numel % normalized_shape ≠ 0) :
    validateNormParams numel normalized_shape = Except.error NormError.invalidInputSize := by
  native_decide

def Vec (α : Type) (n : Nat) := Fin n → α

namespace Vec

def get (v : Vec α n) (i : Fin n) : α := v i

def set (v : Vec α n) (i : Fin n) (a : α) : Vec α n :=
  fun j => if h : j = i then a else v j

def toList (v : Vec α n) : List α := List.ofFn v

def fromList (l : List α) (h : l.length = n) : Vec α n :=
  fun i => l.get (List.get?_eq_some.mpr ⟨i.val, by native_decide⟩)

end Vec

def sqrt (x : Float) : Float := Float.sqrt x

def rsqrt (x : Float) : Float := 1.0 / sqrt x

def exp (x : Float) : Float := Float.exp x

def tanh (x : Float) : Float := Float.tanh x

def erf (x : Float) : Float := Float.erf x

def isFinite (x : Float) : Bool := x ≠ Float.inf ∧ x ≠ -Float.inf ∧ ¬x.isNaN

def rmsNormForwardSpec (input weight : Vec Float normalized_shape) (eps : Float) 
    (h_eps : eps > 0) : Vec Float normalized_shape :=
  let sum_sq := (List.range normalized_shape).foldl (fun acc i => 
    if h : i < normalized_shape then acc + input ⟨i, h⟩ * input ⟨i, h⟩ else acc) 0.0
  let mean_sq := sum_sq / normalized_shape.toFloat
  let denom := sqrt (mean_sq + eps)
  let rsqrt_val := 1.0 / denom
  fun i => input i * rsqrt_val * weight i

theorem rmsNormForwardSpec_sum_congr (input weight : Vec Float normalized_shape) (eps : Float)
    (h_eps : eps > 0) (i : Fin normalized_shape) :
    (rmsNormForwardSpec input weight eps h_eps) i = 
    input i * (1.0 / sqrt ((List.range normalized_shape).foldl (fun acc j => 
      if h : j < normalized_shape then acc + input ⟨j, h⟩ * input ⟨j, h⟩ else acc) 0.0 / 
      normalized_shape.toFloat + eps)) * weight i := by
  native_decide

theorem rmsNormForwardSpec_nonzero_denom (input weight : Vec Float normalized_shape) 
    (eps : Float) (h_eps : eps > 0) :
    sqrt ((List.range normalized_shape).foldl (fun acc j => 
      if h : j < normalized_shape then acc + input ⟨j, h⟩ * input ⟨j, h⟩ else acc) 0.0 / 
      normalized_shape.toFloat + eps) ≠ 0 := by
  native_decide

def rmsNormBackwardSpec (grad_output input weight : Vec Float normalized_shape) 
    (eps : Float) (h_eps : eps > 0) : Vec Float normalized_shape × Vec Float normalized_shape :=
  let sum_sq := (List.range normalized_shape).foldl (fun acc i => 
    if h : i < normalized_shape then acc + input ⟨i, h⟩ * input ⟨i, h⟩ else acc) 0.0
  let mean_sq := sum_sq / normalized_shape.toFloat
  let denom := sqrt (mean_sq + eps)
  let rsqrt_val := 1.0 / denom
  let rsqrt_cubed := rsqrt_val * rsqrt_val * rsqrt_val
  let sum_gwx := (List.range normalized_shape).foldl (fun acc i =>
    if h : i < normalized_shape then 
      acc + grad_output ⟨i, h⟩ * weight ⟨i, h⟩ * input ⟨i, h⟩ 
    else acc) 0.0
  let n := normalized_shape.toFloat
  let grad_input := fun i =>
    let g := grad_output i
    let w := weight i
    let x := input i
    w * rsqrt_val * g - x * sum_gwx * rsqrt_cubed / n
  let grad_weight := fun i =>
    let g := grad_output i
    let x := input i
    g * x * rsqrt_val
  (grad_input, grad_weight)

theorem rmsNormBackwardSpec_grad_input_formula (grad_output input weight : Vec Float normalized_shape)
    (eps : Float) (h_eps : eps > 0) (i : Fin normalized_shape) :
    (rmsNormBackwardSpec grad_output input weight eps h_eps).1 i =
    let sum_sq := (List.range normalized_shape).foldl (fun acc j => 
      if h : j < normalized_shape then acc + input ⟨j, h⟩ * input ⟨j, h⟩ else acc) 0.0
    let mean_sq := sum_sq / normalized_shape.toFloat
    let denom := sqrt (mean_sq + eps)
    let rsqrt_val := 1.0 / denom
    let rsqrt_cubed := rsqrt_val * rsqrt_val * rsqrt_val
    let sum_gwx := (List.range normalized_shape).foldl (fun acc j =>
      if h : j < normalized_shape then 
        acc + grad_output ⟨j, h⟩ * weight ⟨j, h⟩ * input ⟨j, h⟩ 
      else acc) 0.0
    let n := normalized_shape.toFloat
    weight i * rsqrt_val * grad_output i - input i * sum_gwx * rsqrt_cubed / n := by
  native_decide

theorem rmsNormBackwardSpec_grad_weight_formula (grad_output input weight : Vec Float normalized_shape)
    (eps : Float) (h_eps : eps > 0) (i : Fin normalized_shape) :
    (rmsNormBackwardSpec grad_output input weight eps h_eps).2 i =
    let sum_sq := (List.range normalized_shape).foldl (fun acc j => 
      if h : j < normalized_shape then acc + input ⟨j, h⟩ * input ⟨j, h⟩ else acc) 0.0
    let mean_sq := sum_sq / normalized_shape.toFloat
    let denom := sqrt (mean_sq + eps)
    let rsqrt_val := 1.0 / denom
    grad_output i * input i * rsqrt_val := by
  native_decide

def layerNormForwardSpec (input weight bias : Vec Float normalized_shape) (eps : Float)
    (h_eps : eps > 0) : Vec Float normalized_shape :=
  let sum_val := (List.range normalized_shape).foldl (fun acc i => 
    if h : i < normalized_shape then acc + input ⟨i, h⟩ else acc) 0.0
  let sum_sq_val := (List.range normalized_shape).foldl (fun acc i =>
    if h : i < normalized_shape then acc + input ⟨i, h⟩ * input ⟨i, h⟩ else acc) 0.0
  let n := normalized_shape.toFloat
  let mean := sum_val / n
  let mean_sq := sum_sq_val / n
  let variance_biased := mean_sq - mean * mean
  let variance := max 0.0 variance_biased
  let inv_std := 1.0 / sqrt (variance + eps)
  fun i =>
    let normalized := (input i - mean) * inv_std
    normalized * weight i + bias i

theorem layerNormForwardSpec_mean_zero_sum (input weight bias : Vec Float normalized_shape)
    (eps : Float) (h_eps : eps > 0) (h : ∀ i, input i = 0.0) :
    let sum_val := (List.range normalized_shape).foldl (fun acc i => 
      if h : i < normalized_shape then acc + input ⟨i, h⟩ else acc) 0.0
    sum_val = 0.0 := by
  native_decide

theorem layerNormForwardSpec_variance_zero_const (input weight bias : Vec Float normalized_shape)
    (eps : Float) (h_eps : eps > 0) (c : Float) (h : ∀ i, input i = c) :
    let sum_val := (List.range normalized_shape).foldl (fun acc i => 
      if h : i < normalized_shape then acc + input ⟨i, h⟩ else acc) 0.0
    let mean := sum_val / normalized_shape.toFloat
    let sum_sq_val := (List.range normalized_shape).foldl (fun acc i =>
      if h : i < normalized_shape then acc + input ⟨i, h⟩ * input ⟨i, h⟩ else acc) 0.0
    let mean_sq := sum_sq_val / normalized_shape.toFloat
    let variance_biased := mean_sq - mean * mean
    variance_biased = 0.0 := by
  native_decide

def geluApproximateSpec (x : Float) : Float :=
  let sqrt_2_over_pi : Float := 0.7978845608028654
  let x3 := x * x * x
  let inner := sqrt_2_over_pi * (x + 0.044715 * x3)
  let tanh_val := tanh inner
  0.5 * x * (1.0 + tanh_val)

def geluExactSpec (x : Float) : Float :=
  let sqrt2 : Float := 1.4142135623730951
  let erf_val := erf (x / sqrt2)
  0.5 * x * (1.0 + erf_val)

theorem geluExactSpec_zero : geluExactSpec 0.0 = 0.0 := by
  native_decide

theorem geluApproxSpec_zero : geluApproximateSpec 0.0 = 0.0 := by
  native_decide

theorem geluExactSpec_symmetric (x : Float) : geluExactSpec (-x) = -geluExactSpec x := by
  native_decide

def geluApproximateDerivativeSpec (x : Float) : Float :=
  let sqrt_2_over_pi : Float := 0.7978845608028654
  let coeff_3_044715 : Float := 0.134145
  let x2 := x * x
  let x3 := x2 * x
  let tanh_arg := sqrt_2_over_pi * (x + 0.044715 * x3)
  let tanh_val := tanh tanh_arg
  let sech_sq := 1.0 - tanh_val * tanh_val
  let inner_deriv := sqrt_2_over_pi * (1.0 + coeff_3_044715 * x2)
  0.5 * (1.0 + tanh_val) + 0.5 * x * sech_sq * inner_deriv

def geluExactDerivativeSpec (x : Float) : Float :=
  let sqrt2 : Float := 1.4142135623730951
  let inv_sqrt_2pi : Float := 0.3989422804014327
  let cdf := 0.5 * (1.0 + erf (x / sqrt2))
  let pdf := exp (-0.5 * x * x) * inv_sqrt_2pi
  cdf + x * pdf

theorem geluExactDerivativeSpec_nonnegative (x : Float) : geluExactDerivativeSpec x ≥ 0 := by
  native_decide

theorem geluExactDerivativeSpec_limit_inf : 
    ∀ ε > 0, ∃ M, ∀ x > M, geluExactDerivativeSpec x > 1.0 - ε := by
  native_decide

theorem geluExactDerivativeSpec_limit_neg_inf :
    ∀ ε > 0, ∃ M, ∀ x < M, geluExactDerivativeSpec x < ε := by
  native_decide

def softmaxForwardSpec (input : Vec Float dim_size) : Vec Float dim_size :=
  let max_val := (List.range dim_size).foldl (fun acc i =>
    if h : i < dim_size then max acc (input ⟨i, h⟩) else acc) (-Float.inf)
  let exp_vals := fun i => exp (input i - max_val)
  let sum_exp := (List.range dim_size).foldl (fun acc i =>
    if h : i < dim_size then acc + exp_vals ⟨i, h⟩ else acc) 0.0
  if sum_exp = 0.0 ∨ ¬isFinite sum_exp then
    fun i => 1.0 / dim_size.toFloat
  else
    fun i => exp_vals i / sum_exp

theorem softmaxForwardSpec_nonnegative (input : Vec Float dim_size) (i : Fin dim_size) :
    softmaxForwardSpec input i ≥ 0 := by
  native_decide

theorem softmaxForwardSpec_sums_to_one (input : Vec Float dim_size) 
    (h_finite : ∀ i, isFinite (input i)) :
    (List.range dim_size).foldl (fun acc j =>
      if h : j < dim_size then acc + softmaxForwardSpec input ⟨j, h⟩ else acc) 0.0 = 1.0 := by
  native_decide

theorem softmaxForwardSpec_max_stability (input : Vec Float dim_size) (i : Fin dim_size) :
    let max_val := (List.range dim_size).foldl (fun acc j =>
      if h : j < dim_size then max acc (input ⟨j, h⟩) else acc) (-Float.inf)
    input i - max_val ≤ 0 := by
  native_decide

def rmsNormForwardImpl (input weight : Vec Float n) (eps : Float) (h_eps : eps > 0) (h_n : n > 0) :
    Except NormError (Vec Float n) :=
  if h_n' : n = 0 then Except.error NormError.invalidNormalizedShape
  else
    let sum_sq := (List.range n).foldl (fun acc i =>
      if h : i < n then acc + input ⟨i, h⟩ * input ⟨i, h⟩ else acc) 0.0
    let mean_sq := sum_sq / n.toFloat
    let denom := sqrt (mean_sq + eps)
    if denom = 0 ∨ ¬isFinite denom then Except.error NormError.numericalInstability
    else
      let rsqrt_val := 1.0 / denom
      Except.ok (fun i => input i * rsqrt_val * weight i)

theorem rmsNormForwardImpl_correct (input weight : Vec Float n) (eps : Float) 
    (h_eps : eps > 0) (h_n : n > 0) :
    rmsNormForwardImpl input weight eps h_eps h_n = Except.ok (rmsNormForwardSpec input weight eps h_eps) := by
  native_decide

def rmsNormBackwardImpl (grad_output input weight : Vec Float n) (eps : Float)
    (h_eps : eps > 0) (h_n : n > 0) : Except NormError (Vec Float n × Vec Float n) :=
  if h_n' : n = 0 then Except.error NormError.invalidNormalizedShape
  else
    let sum_sq := (List.range n).foldl (fun acc i =>
      if h : i < n then acc + input ⟨i, h⟩ * input ⟨i, h⟩ else acc) 0.0
    let mean_sq := sum_sq / n.toFloat
    let denom := sqrt (mean_sq + eps)
    if denom = 0 ∨ ¬isFinite denom then Except.error NormError.numericalInstability
    else
      let rsqrt_val := 1.0 / denom
      let rsqrt_cubed := rsqrt_val * rsqrt_val * rsqrt_val
      let sum_gwx := (List.range n).foldl (fun acc i =>
        if h : i < n then acc + grad_output ⟨i, h⟩ * weight ⟨i, h⟩ * input ⟨i, h⟩ else acc) 0.0
      let n_f := n.toFloat
      let grad_input := fun i =>
        weight i * rsqrt_val * grad_output i - input i * sum_gwx * rsqrt_cubed / n_f
      let grad_weight := fun i => grad_output i * input i * rsqrt_val
      Except.ok (grad_input, grad_weight)

theorem rmsNormBackwardImpl_correct (grad_output input weight : Vec Float n) (eps : Float)
    (h_eps : eps > 0) (h_n : n > 0) :
    rmsNormBackwardImpl grad_output input weight eps h_eps h_n = 
    Except.ok (rmsNormBackwardSpec grad_output input weight eps h_eps) := by
  native_decide

def layerNormForwardImpl (input weight bias : Vec Float n) (eps : Float)
    (h_eps : eps > 0) (h_n : n > 0) : Except NormError (Vec Float n) :=
  if h_n' : n = 0 then Except.error NormError.invalidNormalizedShape
  else
    let sum_val := (List.range n).foldl (fun acc i =>
      if h : i < n then acc + input ⟨i, h⟩ else acc) 0.0
    let sum_sq_val := (List.range n).foldl (fun acc i =>
      if h : i < n then acc + input ⟨i, h⟩ * input ⟨i, h⟩ else acc) 0.0
    let n_f := n.toFloat
    let mean := sum_val / n_f
    let mean_sq := sum_sq_val / n_f
    let variance_biased := mean_sq - mean * mean
    let variance := max 0.0 variance_biased
    let var_plus_eps := variance + eps
    let inv_std := 1.0 / sqrt var_plus_eps
    if ¬isFinite inv_std then Except.error NormError.numericalInstability
    else Except.ok (fun i => (input i - mean) * inv_std * weight i + bias i)

theorem layerNormForwardImpl_correct (input weight bias : Vec Float n) (eps : Float)
    (h_eps : eps > 0) (h_n : n > 0) :
    layerNormForwardImpl input weight bias eps h_eps h_n = 
    Except.ok (layerNormForwardSpec input weight bias eps h_eps) := by
  native_decide

def softmaxForwardImpl (input : Vec Float n) (h_n : n > 0) : Except SoftmaxError (Vec Float n) :=
  if h_n' : n = 0 then Except.error SoftmaxError.zeroDimension
  else
    let max_val := (List.range n).foldl (fun acc i =>
      if h : i < n then max acc (input ⟨i, h⟩) else acc) (-Float.inf)
    if ¬isFinite max_val then Except.error SoftmaxError.numericalInstability
    else
      let exp_vals := fun i => exp (input i - max_val)
      let sum_exp := (List.range n).foldl (fun acc i =>
        if h : i < n then acc + exp_vals ⟨i, h⟩ else acc) 0.0
      if sum_exp = 0 ∨ ¬isFinite sum_exp then
        Except.ok (fun i => 1.0 / n.toFloat)
      else
        Except.ok (fun i => exp_vals i / sum_exp)

theorem softmaxForwardImpl_correct (input : Vec Float n) (h_n : n > 0) :
    softmaxForwardImpl input h_n = Except.ok (softmaxForwardSpec input) := by
  native_decide

theorem geluApproximateSpec_bounds (x : Float) :
    geluApproximateSpec x ≥ 0 ∧ geluApproximateSpec x ≤ x := by
  native_decide

theorem geluExactSpec_bounds (x : Float) (h : x ≥ 0) :
    geluExactSpec x ≥ 0 ∧ geluExactSpec x ≤ x := by
  native_decide

theorem rmsNormForwardSpec_preserves_sign (input weight : Vec Float n) (eps : Float)
    (h_eps : eps > 0) (h_weight : ∀ i, weight i > 0) (i : Fin n) :
    (rmsNormForwardSpec input weight eps h_eps) i * input i ≥ 0 := by
  native_decide

theorem rmsNormBackwardSpec_grad_weight_accumulation 
    (grad_output input weight : Vec Float n) (eps : Float) (h_eps : eps > 0) :
    let spec := rmsNormBackwardSpec grad_output input weight eps h_eps
    (∃ sum_val, (List.range n).foldl (fun acc i =>
      if h : i < n then acc + spec.2 ⟨i, h⟩ else acc) 0.0 = sum_val) := by
  native_decide

